metadata.er-schema:
{
  "title": "looply · 多语言模块 实体关系图",
  "version": "v2.3 · 2026-06-22",
  "tables": [
    {
      "name": "language",
      "comment": "语言",
      "columns": [
        {
          "name": "language_code",
          "comment": "语言代码（如en/fr/de）",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "language_name",
          "comment": "语言名称（英文）",
          "constraint": ""
        },
        {
          "name": "language_name_local",
          "comment": "本地语言名称",
          "constraint": ""
        },
        {
          "name": "rtl",
          "comment": "是否从右到左",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态",
          "constraint": ""
        }
      ],
      "note": "ISO 639-1 作主键，外部引用（归属 Market 模块管理）"
    },
    {
      "name": "translation",
      "comment": "翻译内容",
      "columns": [
        {
          "name": "translation_id",
          "comment": "翻译ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "resource_type",
          "comment": "资源类型（开放字段，由业务模块注册）",
          "constraint": ""
        },
        {
          "name": "resource_id",
          "comment": "资源ID",
          "constraint": ""
        },
        {
          "name": "field_name",
          "comment": "字段名",
          "constraint": ""
        },
        {
          "name": "source_language_code",
          "comment": "源语言",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "language_code",
          "comment": "目标语言",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "translated_value",
          "comment": "翻译内容",
          "constraint": ""
        },
        {
          "name": "translation_source",
          "comment": "翻译来源（ai/manual）",
          "constraint": ""
        },
        {
          "name": "source_version",
          "comment": "源内容版本号",
          "constraint": ""
        },
        {
          "name": "source_hash",
          "comment": "源内容哈希",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态（translated/outdated）",
          "constraint": ""
        }
      ],
      "note": "EAV 单表，存储所有语言版本（含源语言）。每条记录是当前有效版本。源语言记录的 source_language_code = language_code，translation_source = manual。唯一键：resource_type+resource_id+field_name+source_language_code+language_code"
    },
    {
      "name": "glossary_concept",
      "comment": "术语概念",
      "columns": [
        {
          "name": "concept_id",
          "comment": "概念ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "source_language_code",
          "comment": "源语言",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "source_term",
          "comment": "源术语",
          "constraint": ""
        },
        {
          "name": "rule_type",
          "comment": "规则类型（do_not_translate/mandatory）",
          "constraint": ""
        },
        {
          "name": "context",
          "comment": "使用场景说明",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态（active/deprecated）",
          "constraint": ""
        }
      ],
      "note": "术语管理的核心实体，一个概念对应一个源词。rule_type 决定翻译约束强度"
    },
    {
      "name": "glossary_translation",
      "comment": "术语翻译",
      "columns": [
        {
          "name": "glossary_translation_id",
          "comment": "术语翻译ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "concept_id",
          "comment": "归属术语概念",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "target_language_code",
          "comment": "目标语言",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "translated_term",
          "comment": "标准译法",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态（active/deprecated）",
          "constraint": ""
        }
      ],
      "note": "术语在各目标语言中的标准译法。concept_id + target_language_code 联合唯一"
    },
    {
      "name": "translatable_field_config",
      "comment": "可翻译字段配置",
      "columns": [
        {
          "name": "config_id",
          "comment": "配置ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "resource_type",
          "comment": "资源类型（开放字段，由业务模块注册）",
          "constraint": ""
        },
        {
          "name": "resource_label",
          "comment": "资源类型显示名称（业务模块注册时提供）",
          "constraint": ""
        },
        {
          "name": "field_name",
          "comment": "字段标识",
          "constraint": ""
        },
        {
          "name": "field_label",
          "comment": "字段显示名称",
          "constraint": ""
        },
        {
          "name": "field_type",
          "comment": "字段类型（text/image/rich_text）",
          "constraint": ""
        },
        {
          "name": "key_type",
          "comment": "Key类型（entity_field/static_content）",
          "constraint": ""
        },
        {
          "name": "source_system",
          "comment": "来源系统",
          "constraint": ""
        },
        {
          "name": "sort_order",
          "comment": "排序权重",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态（active/inactive/deprecated）",
          "constraint": ""
        }
      ],
      "note": "注册表模式：业务模块注册可翻译字段。key_type 用于分类展示：entity_field（业务实体字段）/ static_content（页面文案/法律文档等）。resource_type + field_name 联合唯一"
    }
  ],
  "relations": [
    {
      "from": "translation",
      "to": "language",
      "type": "N:1",
      "label": "目标语言",
      "color": "#7B1FA2",
      "penwidth": 1.4
    },
    {
      "from": "translation",
      "to": "language",
      "type": "N:1",
      "label": "源语言",
      "color": "#7B1FA2",
      "penwidth": 1.2
    },
    {
      "from": "glossary_concept",
      "to": "language",
      "type": "N:1",
      "label": "源语言",
      "color": "#2E7D32"
    },
    {
      "from": "glossary_translation",
      "to": "glossary_concept",
      "type": "N:1",
      "label": "归属概念",
      "color": "#2E7D32",
      "penwidth": 1.4
    },
    {
      "from": "translatable_field_config",
      "to": "translation",
      "type": "",
      "label": "字段规则约束",
      "color": "#2E7D32",
      "style": "dashed",
      "penwidth": 1.0
    },
    {
      "from": "glossary_concept",
      "to": "translation",
      "type": "",
      "label": "术语约束",
      "color": "#2E7D32",
      "style": "dashed",
      "penwidth": 1.0
    }
  ],
  "design_rules": {
    "localized_content_architecture": "数据分类原则：Structured Data（价格/库存/尺寸/品牌ID等语言无关数据）存业务主表；Localized Content（标题/描述/SEO/文案/图片等需多语言的内容）全部存翻译模块 translation 表，含源语言。业务表不存任何文本字段",
    "eav_pattern": "translation 表采用 EAV 模式（resource_type + resource_id + field_name），一张表存储所有翻译内容。resource_type 为开放 VARCHAR，翻译模块不限定取值范围，由业务模块自行定义",
    "translation_current_record": "translation 表每条记录代表该资源字段+语言方向的当前有效版本。翻译完成后原地更新，不在主表追加历史行",
    "translation_no_history_in_main_table": "translation 主表不保留历史版本；历史变更通过 source_hash + source_version 追踪源内容变化，可选接入版本历史表",
    "translation_unique_key": "translation 唯一性约束由五列联合保证：resource_type + resource_id + field_name + source_language_code + language_code。相同资源字段同一翻译方向只有一条当前记录",
    "translation_status_lifecycle": "translation 状态生命周期：translated（翻译完成，当前有效）→ outdated（源内容变更触发）。本期无审核环节，AI 翻译或手动编辑保存后直接进入 translated",
    "auto_translation_path": "统一自动翻译路径：源语言内容编辑保存 → 其他语言标记 outdated → 系统自动重译 → 写入 translation 表（status=translated）。translation_source 字段记录来源（ai/manual）。本期无审核环节",
    "translation_strategy": "统一策略：所有内容 AI 自动翻译，运营可在翻译详情页手动修正。source_hash 检测源内容变化，status=outdated 触发重译",
    "key_type_semantics": "translatable_field_config.key_type 用于分类展示，不决定数据流：entity_field（来自业务实体的字段，如 product.title）；static_content（页面文案/法律文档/通知模板等非业务实体内容）。两种类型的数据存储和触发链路完全一致，均存翻译模块",
    "source_language_record": "源语言记录规则：所有类型的源语言内容都存 translation 表，source_language_code = language_code，translation_source = manual，表示原始录入而非翻译产物。前端统一查翻译服务，不区分源/目标语言",
    "language_fk": "翻译关联 language_code（ISO 639-1），不建 locale 实体。BCP 47 locale 在运行时由 language_code + country_code 拼接",
    "glossary_concept_model": "术语采用概念模型：glossary_concept（一个源词）→ glossary_translation（多目标语言译法）。一个概念下挂多语言翻译，显式关联。禁译词（do_not_translate）无需创建 glossary_translation 行，系统自动保留原文",
    "glossary_enforcement": "术语表规则类型：do_not_translate（禁译词，保留原文）、mandatory（强制术语，必须使用指定译法）",
    "glossary_context_field": "glossary_concept.context 字段记录使用场景说明，用于消歧义和指导翻译",
    "translatable_field_config_registry": "translatable_field_config 采用注册表模式：各业务模块主动注册需要翻译的字段。只有显式注册的字段才会进入翻译流程。翻译模块不主动扫描业务模块",
    "field_type_usage": "translatable_field_config.field_type 决定前台编辑器类型：text（文本输入）、image（图片上传，translated_value 存 CDN URL）、rich_text（富文本编辑器）",
    "key_naming_convention": "Key 名称 = resource_type + \".\" + field_name 拼接显示。entity_field：product.title；static_content：ui.cart.btn.checkout。命名空间层级是约定规范，不是数据库强制",
    "resource_type_open_field": "resource_type 为开放 VARCHAR，不使用枚举约束。entity_field 类如 product/listing/spu/sku/category/brand/series/attribute/attribute_option/condition_grade；static_content 类如 ui/legal/pdp_template/content/email_template/message_template",
    "frontend_resolution": "前端读取链路统一：BFF 从商品服务取结构化数据 + 从翻译服务取所有文本内容，不区分 key_type、不区分源/目标语言，统一按 resource_type + resource_id + field_name + language_code 查询",
    "multi_source_language": "支持多源语言：不同商品可有不同源语言（由商家 default_content_language 决定）。translation.source_language_code 标记\"从哪个语言翻译来的\"，查询时按 resource_id + field_name + language_code 查，无需关心源语言",
    "audit_fields": "所有实体统一通过数据库层自动维护审计字段（created_by/created_at/updated_by/updated_at），不在 ER 图中逐表重复列出"
  }
}
